const item = $input.first();
const body = item.json.body ?? {};
const goal = String(body.goal || 'Help me understand and remember this material');
const notes = String(body.notes || '').trim();
const requestedCount = Number(body.questionCount || 5);
const questionCount = Number.isInteger(requestedCount) ? Math.min(50, Math.max(1, requestedCount)) : 5;
const binaries = item.binary ?? {};
const pdfFiles = Object.entries(binaries).filter(([name, file]) =>
  String(file.fileName || name).toLowerCase().endsWith('.pdf') || file.mimeType === 'application/pdf'
);

if (pdfFiles.length === 0) {
  return [{ json: { hasPdf: false, goal, notes, questionCount } }];
}

return pdfFiles.map(([name, file]) => ({
  json: { hasPdf: true, goal, notes, questionCount, fileName: file.fileName || name },
  binary: { data: file },
}));

parameters.text:
=Create a study pack using only the source material below. Follow the learner's goal. If the source does not contain enough information for a requested point, say so in the explanation rather than inventing facts.

Include a multiple-choice quiz in the `questions` array. Generate up to {{ $json.questionCount }} questions; aim for that number when the source supports it, and generate fewer rather than inventing. Each question must have exactly 4 distinct answer options and exactly 1 correct option. Set `answerIndex` to the zero-based index of the correct option (0 is the first option). Make each explanation say why the correct answer follows from the source.

LEARNING GOAL
{{ $json.goal }}

SOURCE MATERIAL
{{ $json.sourceText }}

parameters.jsCode:
const items = $input.all();
if (!items.length) throw new Error('No PDF text was extracted.');

const first = items[0].json;
const notes = String(first.notes || '').trim();
const pdfText = items.map((item, index) => {
  const text = String(item.json.text || '').trim();
  if (!text) return '';
  const filename = item.json.fileName || `PDF ${index + 1}`;
  return `--- ${filename} ---\n${text}`;
}).filter(Boolean);
const sourceText = [notes, ...pdfText].filter(Boolean).join('\n\n');
if (!sourceText.trim()) {
  throw new Error('The uploaded PDF produced no readable text. If it is a scanned document, add OCR before generating the study pack.');
}

return [{ json: { goal: first.goal, sourceText, questionCount: first.questionCount } }];

const item = $input.first();
const sourceText = String(item.json.notes || '').trim();
if (!sourceText) throw new Error('No source material was received. Upload a PDF or paste notes before generating a study pack.');
return [{ json: { goal: item.json.goal, sourceText, questionCount: item.json.questionCount } }];
